// ShaderToy code for "Celestial Vortex"
// Precision camera placement with layered depth structure

#define MAX_STEPS 128
#define MAX_DIST 100.0
#define SURF_DIST 0.001
#define PI 3.14159265359

mat2 rot(float a) { return mat2(cos(a), -sin(a), sin(a), cos(a)); }

float sdSphere(vec3 p, float r) { return length(p) - r; }
float sdTorus(vec3 p, vec2 t) { return length(vec2(length(p.xz)-t.x,p.y))-t.y; }
float sdCapsule(vec3 p, vec3 a, vec3 b, float r) {
    vec3 pa = p - a, ba = b - a;
    float h = clamp(dot(pa,ba)/dot(ba,ba), 0.0, 1.0);
    return length(pa - ba*h) - r;
}

float smin(float a, float b, float k) { 
    float h = clamp(0.5 + 0.5*(a-b)/k, 0.0, 1.0); 
    return mix(a, b, h) - k*h*(1.0-h); 
}

vec3 palette(float t) {
    vec3 a = vec3(0.8, 0.6, 0.4);
    vec3 b = vec3(0.2, 0.4, 0.6);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.00, 0.10, 0.20);
    return a + b*cos(6.28318*(c*t+d));
}

float hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898,78.233))) * 43758.5453); }

float noise(vec2 p) {
    vec2 i = floor(p); vec2 f = fract(p);
    float a = hash(i), b = hash(i + vec2(1,0));
    float c = hash(i + vec2(0,1)), d = hash(i + vec2(1,1));
    vec2 u = f*f*(3.0-2.0*f);
    return mix(a, b, u.x) + (c - a)*u.y*(1.0 - u.x) + (d - b)*u.x*u.y;
}

struct Scene {
    float d; vec3 col; vec3 emis; float alpha;
};

Scene map(vec3 p) {
    float t = iTime;
    Scene scene = Scene(1e5, vec3(0), vec3(0), 0.0);

    // Central Pulsar
    vec3 orbPos = p;
    float orbScale = 1.8 + sin(t)*0.2;
    float disp = sin(orbPos.x*8.0 + t*4.0)*0.15 
               + sin(orbPos.z*5.0 + t*3.0)*0.2 
               + sin(orbPos.y*3.0 + t*2.0)*0.1;
    float orb = sdSphere(p, orbScale - disp*0.3);
    if(orb < scene.d) {
        scene.d = orb;
        scene.col = palette(t*0.2 + length(p)*0.1);
        scene.emis = vec3(1.0,0.8,0.6) * (sin(t*2.0)*0.3+0.7)*3.0;
        scene.alpha = 0.8;
    }

    // Orbital Torus System (mid-ground)
    vec3 q = p;
    q.xz *= rot(t);
    q.xy *= rot(t*0.5);
    float ring = sdTorus(q - vec3(0,0,6.0), vec2(3.5, 0.4));
    ring = smin(ring, sdCapsule(q, vec3(-1,0,6), vec3(1,0,6), 0.3), 0.5);
    ring = smin(ring, sdCapsule(q, vec3(0,-1,6), vec3(0,1,6), 0.3), 0.5);
    if(ring < scene.d) {
        scene.d = ring;
        scene.col = vec3(0.4,0.6,1.0) * (0.8 + sin(t + q.z)*0.2);
        scene.emis = vec3(0.3,0.5,1.0) * (0.5 + sin(t*2.0 + q.x*10.0)*0.5);
    }

    // Particle Nebula
    vec3 pp = p * 2.0 + vec3(t*0.5, t*0.3, t*0.4);
    float pn = noise(pp.xy) * noise(pp.yz) * noise(pp.zx);
    if(pn > 0.7 + sin(t + pp.z*0.5)*0.1) {
        float part = sdSphere(p - vec3(sin(t)*2.0, cos(t*0.7)*2.0, 8.0), 0.2);
        if(part < scene.d) {
            scene.d = part;
            scene.col = mix(vec3(1.0,0.3,0.1), vec3(0.1,0.3,1.0), pn);
            scene.emis = scene.col * 4.0;
        }
    }

    return scene;
}

vec3 calcNormal(vec3 p) {
    vec2 e = vec2(0.001, 0);
    return normalize(map(p).d - vec3(
        map(p-e.xyy).d, map(p-e.yxy).d, map(p-e.yyx).d));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5*iResolution.xy)/iResolution.y;
    vec3 col = vec3(0);
    float t = iTime;

    // Dynamic camera framing
    vec3 ro = vec3(0, 0, -8.0 + sin(t*0.3)*0.5);
    vec3 rd = normalize(vec3(uv, 1.2)); // Wider FOV
    rd.xy *= rot(sin(t*0.2)*0.1); // Gentle camera rotation
    rd.yz *= rot(sin(t*0.15)*0.05);

    // Depth layering
    float dO = 0.0, glow = 0.0;
    vec3 volLight = vec3(0);
    bool hitSurface = false;

    for(int i = 0; i < MAX_STEPS; i++) {
        vec3 p = ro + rd * dO;
        Scene s = map(p);

        if(s.d < SURF_DIST || dO > MAX_DIST) {
            if(dO > MAX_DIST) {
                // Background nebula
                vec2 bgUV = uv * 3.0 + t*0.05;
                float stars = pow(noise(bgUV * 50.0), 50.0) * 2.0;
                stars += pow(noise(bgUV * 100.0), 100.0) * 3.0;
                col += stars * mix(vec3(0.8,0.9,1.0), vec3(1.0,0.9,0.7), noise(bgUV));
                col += vec3(0.02,0.03,0.05) * smoothstep(1.0, 0.5, length(uv));
            }
            break;
        }

        dO += s.d * 0.8;
        float fogFactor = exp(-dO*0.05);
        glow += 0.03/(0.1 + s.d) * fogFactor;
        volLight += s.emis * 0.015 * fogFactor;
    }

    // Surface shading
    if(dO < MAX_DIST) {
        vec3 p = ro + rd * dO;
        Scene s = map(p);
        vec3 normal = calcNormal(p);
        vec3 lightDir = normalize(vec3(1,1,-0.5));

        float diff = max(dot(normal, lightDir), 0.0);
        vec3 refl = reflect(rd, normal);
        float spec = pow(max(dot(refl, lightDir), 0.0), 32.0);

        col = s.col * (diff + 0.1) + spec * 0.5 + s.emis;
        col = mix(col, volLight, 0.3);
        col += glow * s.emis * 0.1;
    }

    // Atmospheric depth
    col = mix(col, vec3(0.02,0.03,0.05), 1.0 - exp(-dO*0.03));

    // Post-processing
    col = pow(col, vec3(0.4545));
    float vignette = 1.0 - smoothstep(0.6, 1.2, length(uv));
    col *= vignette * vignette;
    col += 0.01*noise(uv*100.0 + t); // Subtle noise texture

    fragColor = vec4(col, 1.0);
}
